window.BANCO = window.BANCO || [];
window.BANCO.push({"id":"fuentes","nombre":"Fuentes del Derecho","bloques":[{"id":"fuentes","nombre":"Fuentes del Derecho"}],"calendarios":{"cal2023":{"titulo":"Calendario 2023 (enero a junio)","year":2023,"meses":[1,2,3,4,5,6],"festivos":["2023-01-06","2023-03-20","2023-04-06","2023-04-07","2023-05-01","2023-05-02"],"nota":"Los domingos también van en rojo."},"dic2024":{"titulo":"Calendario diciembre 2024","year":2024,"meses":[12],"festivos":["2024-12-06","2024-12-08","2024-12-25"],"nota":"Los domingos también van en rojo."}},"casos":[],"preguntas":[{"id":"vo-01-001","origen":"votaciones","test":"Clase 1 - Bloque III","n":1,"enunciado":"Según el Código Civil, los usos jurídicos que no sean meramente interpretativos de una declaración de voluntad tendrán la consideración de: (GACE-LI 2019)","opciones":["Costumbre.","Principios generales del derecho.","Ley.","No serán fuente de derecho."],"bloque":"fuentes","precepto":"Art. 1.3 del Código Civil","correcta":0,"justificaciones":["Es esta. Un uso jurídico es una práctica que la gente sigue porque cree que obliga, y el **art. 1.3 del Código Civil** dice que, si no se limita a interpretar lo que alguien ha querido decir, cuenta como **costumbre**.","No. Los principios generales son las ideas de fondo del ordenamiento (buena fe, igualdad). Son la tercera fuente y no tienen nada que ver con los usos.","No. Un uso nace de la práctica de la gente. Una ley la aprueban las Cortes Generales o un parlamento autonómico.","No. Justo al contrario: al tener la consideración de costumbre, sí es fuente del Derecho. Los que se quedan fuera son los usos meramente interpretativos."]},{"id":"vo-01-002","origen":"votaciones","test":"Clase 1 - Bloque III","n":2,"enunciado":"En relación con las fuentes del derecho, y de conformidad con lo establecido en el artículo 1 del Código Civil, señale cuál de las siguientes opciones no es correcta: (ADMVO-P.I. 2021)","opciones":["Carecerán de validez las disposiciones que contradigan otra del mismo rango.","La costumbre solo regirá en defecto de ley aplicable, siempre que no sea contraria a la moral o al orden público, y que resulte probada.","Los principios generales del derecho se aplicarán en defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico.","Los usos jurídicos que no sean meramente interpretativos de una declaración de voluntad tendrán la consideración de costumbre."],"bloque":"fuentes","precepto":"Art. 1.2 del Código Civil","correcta":0,"justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El **art. 1.2 del Código Civil** dice que carecen de validez las disposiciones que contradigan otra de **rango superior**, no del mismo rango. Entre normas del mismo rango no se anulan: la posterior deroga a la anterior.","Es verdadera, así que no se marca. Es el art. 1.3 CC: la costumbre va detrás de la ley y además tiene que ser conforme a la moral y al orden público, y probarse.","Es verdadera, así que no se marca. Es el art. 1.4 CC: los principios se aplican si no hay ley ni costumbre, y además “informan” todo el ordenamiento.","Es verdadera, así que no se marca. Es el párrafo segundo del art. 1.3 CC."],"ojo":"Lee bien el enunciado: pide la que “no es correcta”. Te han cambiado “rango superior” por “mismo rango”, y eso es lo único que falla."},{"id":"vo-01-003","origen":"votaciones","test":"Clase 1 - Bloque III","n":3,"enunciado":"Señale la respuesta correcta en relación con las fuentes del derecho administrativo de conformidad con lo dispuesto en el artículo 1 del Código Civil: (GACE-LI 2021)","opciones":["Los usos jurídicos meramente interpretativos de una declaración de voluntad tendrán la consideración de costumbre.","Los principios generales del derecho se aplicarán directamente en defecto de ley, siempre que no sean contrarios a la moral o al orden público.","Los principios generales del derecho tienen carácter informador del ordenamiento jurídico.","La jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de modo reiterado, establezca el Tribunal Constitucional."],"bloque":"fuentes","precepto":"Art. 1.4 del Código Civil","correcta":2,"justificaciones":["No. Es al revés: los usos que se limitan a interpretar una declaración de voluntad son los que **no** cuentan como costumbre (art. 1.3 CC).","No. Mezcla dos cosas. Lo de “no ser contrarios a la moral o al orden público” es un requisito de la costumbre, y los principios se aplican si no hay ley **ni costumbre**, no solo si no hay ley.","Es esta. El **art. 1.4 CC** dice que los principios generales se aplican en defecto de ley o costumbre, “sin perjuicio de su carácter informador del ordenamiento jurídico”. Es decir, están siempre de fondo, orientando cómo se entienden las demás normas.","No. La doctrina que complementa el ordenamiento es la del **Tribunal Supremo**, no la del Tribunal Constitucional (art. 1.6 CC). Además, la jurisprudencia no es fuente del Derecho: solo complementa."]},{"id":"vo-01-004","origen":"votaciones","test":"Clase 1 - Bloque III","n":4,"enunciado":"Señale la afirmación falsa. Es una norma con rango de ley: (ADVO-PI 2009)","opciones":["Un Decreto Legislativo dictado por el Gobierno.","La Ley de Presupuestos Generales del Estado.","Un Decreto-Ley dictado por el Gobierno.","Una sentencia del Tribunal Constitucional por la que se invalida una ley."],"bloque":"fuentes","precepto":"Arts. 82, 85 y 86 de la Constitución; art. 134 CE","correcta":3,"justificaciones":["Es verdadero que tiene rango de ley: el decreto legislativo lo dicta el Gobierno porque las Cortes le han delegado esa tarea (arts. 82 y 85 CE).","Es verdadero que tiene rango de ley: la aprueban las Cortes Generales, aunque tenga un procedimiento especial (art. 134 CE).","Es verdadero que tiene rango de ley: lo dicta el Gobierno en casos de extraordinaria y urgente necesidad, y luego lo convalida el Congreso (art. 86 CE).","Esta es la falsa, y por eso se marca. Una sentencia del Tribunal Constitucional **no es una norma**: no crea una ley, sino que expulsa del ordenamiento la que es inconstitucional."],"ojo":"Piénsalo como un árbitro: el Tribunal Constitucional puede anular una jugada, pero no escribe el reglamento."},{"id":"vo-01-005","origen":"votaciones","test":"Clase 1 - Bloque III","n":5,"enunciado":"El principio de jerarquía de las fuentes en el Derecho Administrativo: (ADVO-PI 2010)","opciones":["Implica que las normas estatales ostentarán mayor rango que las normas autonómicas.","Determina que, en caso de contradicción entre normas, la inferior deroga a la superior.","No se aplica en las relaciones entre las leyes orgánicas y las leyes ordinarias.","Implica que la ley se subordina jerárquicamente al reglamento."],"bloque":"fuentes","precepto":"Art. 9.3 CE; art. 1.2 del Código Civil; art. 81 CE","correcta":2,"justificaciones":["No. Entre una norma estatal y una autonómica no manda el rango, sino la **competencia**: cada una vale en su materia.","No. Es justo al revés. Si chocan, gana la superior. La norma inferior que contradiga a la superior no es válida (art. 1.2 CC).","Es esta. Ley orgánica y ley ordinaria tienen **el mismo rango**: su diferencia es de materia y de mayoría, no de jerarquía (art. 81 CE). Cada una tiene su terreno, así que no se aplica entre ellas el principio de jerarquía.","No. También está al revés. El reglamento es el que se subordina a la ley, nunca la ley al reglamento."]},{"id":"vo-01-006","origen":"votaciones","test":"Clase 1 - Bloque III","n":6,"enunciado":"La reserva de ley significa que: (ADVO-PI 2007)","opciones":["La ley se sitúa en la posición más elevada del sistema normativo.","Es imposible negarse a la aplicación o cumplimiento de la ley.","El enjuiciamiento de la Ley corresponde en exclusiva al Tribunal Constitucional.","Determinadas materias establecidas en la Constitución solo pueden ser reguladas por una norma con rango de Ley."],"bloque":"fuentes","precepto":"Arts. 53.1 y 81 CE","correcta":3,"justificaciones":["No. Eso describe la **jerarquía** o la superioridad de la ley, que es otra idea distinta.","No. Eso se parece a la obligación de cumplir las normas (art. 9.1 CE), pero no es la reserva de ley.","No. Eso es el control de constitucionalidad, que corresponde al Tribunal Constitucional. No dice qué materias tiene que regular una ley.","Es esta. La reserva de ley significa que la Constitución “guarda” ciertas materias para que solo las regule una **norma con rango de ley**. Por ejemplo, los derechos y libertades (art. 53.1 CE). Un reglamento no puede entrar a regularlas por su cuenta."]},{"id":"vo-01-007","origen":"votaciones","test":"Clase 1 - Bloque III","n":7,"enunciado":"De acuerdo con el Código Civil, señale cuál NO es una fuente del Derecho Administrativo: (GACE 2017)","opciones":["La costumbre.","Los actos administrativos.","La Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa.","Los principios generales del Derecho."],"bloque":"fuentes","precepto":"Art. 1.1 del Código Civil","correcta":1,"justificaciones":["Sí es fuente: el art. 1.1 CC la cita junto a la ley y los principios generales.","Es esta. Las fuentes crean normas que valen para todos. Un **acto administrativo**, en cambio, aplica las normas a un caso concreto, como una multa o una licencia. No forma parte del ordenamiento, sino que se somete a él.","Sí es fuente: es una ley, y la ley es la primera de las fuentes del art. 1.1 CC.","Sí es fuente: es la tercera del art. 1.1 CC."],"ojo":"Una multa no es una norma: es lo que te pasa a ti por incumplir una norma."},{"id":"vo-01-008","origen":"votaciones","test":"Clase 1 - Bloque III","n":8,"enunciado":"En la Administración General del Estado, de conformidad con el artículo 24.1 de la Ley 50/1997, las decisiones del Gobierno de la Nación y de sus miembros revisten las formas siguientes: (ADVO-LI 2017)","opciones":["Reales Decretos Legislativos y Reales Decretos-Leyes, las decisiones que aprueban normas reglamentarias.","Órdenes Ministeriales, las disposiciones y resoluciones de los Ministros y Secretarios de Estado.","Reales Decretos acordados en Consejo de Ministros, las que aprueben normas reglamentarias de la competencia del Consejo de Ministros y las resoluciones que deban adoptar dicha forma jurídica.","Reales Decretos del Ministro de Presidencia, las decisiones de las Comisiones Delegadas cuando la competencia corresponda a distintos Ministros."],"bloque":"fuentes","precepto":"Art. 24.1.c) de la Ley 50/1997","correcta":2,"justificaciones":["No. Los Reales Decretos Legislativos y los Reales Decretos-leyes aprueban las normas de los arts. 82 y 86 de la Constitución, que tienen rango de ley (art. 24.1.a). Te han cambiado eso por “normas reglamentarias”, y los reglamentos no tienen ese rango.","No. Sobran los “Secretarios de Estado”. Las Órdenes Ministeriales son disposiciones y resoluciones solo de los Ministros (art. 24.1.f).","Es esta. Coincide con el **art. 24.1.c) de la Ley 50/1997**: lo que aprueba el Consejo de Ministros como reglamento de su competencia, y las resoluciones que deban tener esa forma, sale como Real Decreto acordado en Consejo de Ministros.","No. El “Real Decreto del Ministro de Presidencia” no existe. Lo que decide una Comisión Delegada es un Acuerdo, que toma forma de Orden del Ministro competente, o del Ministro de la Presidencia si la competencia es de varios Ministros (art. 24.1.e)."],"ojo":"Real Decreto solo hay del Presidente del Gobierno o acordado en Consejo de Ministros. Un Ministro, por sí solo, dicta Órdenes."},{"id":"vo-01-009","origen":"votaciones","test":"Clase 1 - Bloque III","n":9,"enunciado":"Según la Ley del Gobierno, las disposiciones y resoluciones de los Ministros revisten la forma de Órdenes Ministeriales. Cuando la disposición o resolución afecte a varios Departamentos revestirá la forma de: (GACE-LI 2017)","opciones":["Orden del Ministro de la Presidencia, dictada a propuesta de los Ministros interesados.","Real Decreto del Ministro de la Presidencia.","Real Decreto, dictado a propuesta de los Ministros interesados.","Acuerdo del Consejo de Ministros, dictada a propuesta de los Ministros interesados."],"bloque":"fuentes","precepto":"Art. 24.1.f) de la Ley 50/1997","correcta":0,"justificaciones":["Es esta. El **art. 24.1.f) de la Ley 50/1997** dice que, si afecta a varios Departamentos (varios Ministerios), toma forma de “Orden del Ministro de la Presidencia”, dictada a propuesta de los Ministros interesados. Sigue siendo una Orden, porque la decisión sigue siendo de nivel ministerial.","No. Un Ministro no dicta Reales Decretos: esa forma es solo del Presidente del Gobierno o del Consejo de Ministros. Lo bueno es “Orden” del Ministro de la Presidencia.","No. La propuesta de los Ministros interesados sí está en la norma, pero la forma es Orden del Ministro de la Presidencia, no Real Decreto.","No. El Acuerdo del Consejo de Ministros es para decisiones de ese órgano que no deban ser Real Decreto (art. 24.1.d). Aquí la decisión es de Ministros, no del Consejo."]},{"id":"vo-01-010","origen":"votaciones","test":"Clase 1 - Bloque III","n":10,"enunciado":"Señale, por favor, la afirmación correcta. La jerarquía entre Reglamentos: (GACE-LI 2008)","opciones":["No existe. La jerarquía se plantea entre leyes y reglamentos, pero no entre estos.","Existe. En este sentido, los Reales Decretos Leyes y los Reales Decretos Legislativos están por encima del resto de reglamentos.","Existe. Así, las disposiciones aprobadas por Real Decreto del Presidente del Gobierno están por encima de los Reales Decretos del Consejo de Ministros.","Existe. Por ello, las disposiciones aprobadas por Real Decreto son jerárquicamente superiores a las Órdenes Ministeriales."],"bloque":"fuentes","precepto":"Art. 24.2 de la Ley 50/1997","correcta":3,"justificaciones":["No. Entre reglamentos sí hay jerarquía. La fija el art. 24.2 de la Ley 50/1997, y además el art. 128.3 de la Ley 39/2015 dice que una disposición administrativa no puede vulnerar otra de rango superior.","No. Los Reales Decretos-leyes y los Reales Decretos Legislativos no son reglamentos: son normas con rango de ley (arts. 82 y 86 CE). Por eso no entran en esta escala.","No. El Real Decreto del Presidente y el acordado en Consejo de Ministros están en el mismo escalón, el primero (art. 24.2.1.º). Ninguno está por encima del otro.","Es esta. El **art. 24.2 de la Ley 50/1997** tiene dos escalones: primero, lo aprobado por Real Decreto (del Presidente o acordado en Consejo de Ministros); segundo, lo aprobado por Orden Ministerial. Por tanto, el Real Decreto manda sobre la Orden."]},{"id":"vo-01-011","origen":"votaciones","test":"Clase 1 - Bloque III","n":11,"enunciado":"Según el artículo 23 de la Ley 50/1997, del Gobierno, los reglamentos se ajustarán a las siguientes normas de jerarquía: (GACE-LI 2013)","opciones":["1º Disposiciones aprobadas por Reales Decretos Legislativos y Reales Decretos Leyes. 2º Disposiciones aprobadas por Reales Decretos del Presidente del Gobierno. 3º Disposiciones aprobadas por Reales Decretos acordados en Consejo de Ministros.","1º Disposiciones aprobadas por Real Decreto del Presidente del Gobierno o del Consejo de Ministros. 2º Disposiciones aprobadas por Orden Ministerial.","1º Disposiciones aprobadas por Reales Decretos Legislativos y Reales Decretos Leyes. 2º Disposiciones aprobadas por Real Decreto del Presidente del Gobierno o del Consejo de Ministros.","Todos los reglamentos tendrán el mismo rango jerárquico."],"bloque":"fuentes","precepto":"Art. 24.2 de la Ley 50/1997","correcta":1,"justificaciones":["No. Tiene dos fallos. Mete Reales Decretos Legislativos y Reales Decretos-leyes, que tienen rango de ley y no son reglamentos. Y separa en dos escalones el Real Decreto del Presidente y el del Consejo de Ministros, cuando comparten el primero.","Es esta. Son los dos escalones del **art. 24.2 de la Ley 50/1997**: 1.º lo aprobado por Real Decreto del Presidente o acordado en Consejo de Ministros; 2.º lo aprobado por Orden Ministerial. Dos niveles, fáciles de recordar: Real Decreto arriba, Orden abajo.","No. El primer escalón es inventado: los Reales Decretos Legislativos y los Reales Decretos-leyes son normas con rango de ley, no reglamentos. Además, se olvida de la Orden Ministerial.","No. Sí hay jerarquía entre reglamentos, y por eso la ley los ordena en dos niveles (art. 24.2). Decir que todos tienen el mismo rango va contra esa ordenación."],"ojo":"El enunciado cita el art. 23 porque ahí estaba esta regla cuando se puso la pregunta (2013). Desde el 2 de octubre de 2016 la jerarquía está en el art. 24.2, y el art. 23 habla de la entrada en vigor. El contenido es el mismo."},{"id":"vo-01-013","origen":"votaciones","test":"Clase 1 - Bloque III","n":13,"enunciado":"Según la CE, la autorización de las Cortes para la redacción de un texto refundido de ley mediante Decreto Legislativo: (GACE-LI 2015)","opciones":["Se otorga mediante Ley de Bases y debe circunscribirse a la mera formulación de un texto único.","Se otorga mediante Ley de Bases y puede incluir la regularización, aclaración y armonización los textos legales que han de ser refundidos.","Se otorga mediante Ley ordinaria y puede incluir la regularización, aclaración y armonización los textos legales que han de ser refundidos.","Se otorga mediante Ley ordinaria y debe circunscribirse a la mera formulación de un texto único."],"bloque":"fuentes","precepto":"Art. 82.2 y 82.5 de la Constitución","correcta":2,"justificaciones":["No. Falla dos veces. Para refundir se usa ley ordinaria, no ley de bases (art. 82.2 CE). Y no “debe” limitarse a un texto único: la autorización puede también permitir regularizar, aclarar y armonizar (art. 82.5 CE).","No. La segunda parte es buena, pero la ley de bases es para textos articulados. Para refundir se usa ley ordinaria (art. 82.2 CE).","Es esta. Refundir se autoriza por ley ordinaria (**art. 82.2 CE**). Y la autorización dice hasta dónde llega: solo juntar los textos en uno, o también regularizarlos, aclararlos y armonizarlos (**art. 82.5 CE**). Así que “puede incluir” esas tareas.","No. La ley ordinaria es correcta, pero sobra el “debe”. La mera formulación de un texto único es una de las dos posibilidades, no la única (art. 82.5 CE)."],"ojo":"Regla rápida: texto articulado, ley de bases. Texto refundido, ley ordinaria."},{"id":"vo-01-014","origen":"votaciones","test":"Clase 1 - Bloque III","n":14,"enunciado":"De conformidad con el artículo 82 de la Constitución Española, ¿qué caracteriza a una ley de bases? (ADMVO-PI 2016)","opciones":["Que fija la normativa básica del Estado.","Que es de rango superior a una ley ordinaria.","Que su objeto es la formación de textos articulados.","Que tiene que ser convalidada por el Congreso de los Diputados."],"bloque":"fuentes","precepto":"Art. 82.2 de la Constitución","correcta":2,"justificaciones":["No. Se parece por la palabra, pero “bases” aquí no significa normativa básica del Estado. Son los principios y criterios que se le dan al Gobierno para redactar un texto articulado (art. 82.4 CE).","No. Una ley de bases no tiene más rango que una ley ordinaria: las dos son leyes aprobadas por las Cortes. El art. 82 CE solo les da funciones distintas.","Es esta. El **art. 82.2 CE** dice que la delegación se otorga por ley de bases cuando su objeto es “la formación de textos articulados”. Las Cortes marcan las pautas y el Gobierno redacta el texto completo en forma de artículos.","No. La convalidación por el Congreso es propia de los decretos-leyes (art. 86.2 CE). La ley de bases la aprueban las propias Cortes, así que nadie tiene que convalidarla."]},{"id":"vo-01-015","origen":"votaciones","test":"Clase 1 - Bloque III","n":15,"enunciado":"Indique la respuesta correcta en relación con los Decretos Legislativos: (GACE-LI 2014)","opciones":["Cuando una proposición de ley fuere contraria a una delegación legislativa en vigor, el Gobierno está facultado para oponerse a su tramitación.","La delegación legislativa deberá otorgarse mediante una ley de bases cuando su objeto sea refundir varios textos legales.","La delegación legislativa no se agota por el uso que de ella haga el Gobierno mediante la publicación de la norma correspondiente.","Las leyes de delegación no podrán establecer formulas adicionales de control por ser competencia única de los Tribunales."],"bloque":"fuentes","precepto":"Art. 84 de la Constitución","correcta":0,"justificaciones":["Es esta. Lo dice el **art. 84 CE**: si una proposición de ley (o una enmienda) va contra una delegación legislativa en vigor, el Gobierno puede oponerse a que se tramite. Tiene sentido: las Cortes ya le han encargado esa tarea y no conviene pisarla.","No. Han cambiado la ley: para refundir textos legales es ley ordinaria. La ley de bases es para formar textos articulados (art. 82.2 CE).","No. Es justo lo contrario: la delegación “se agota” cuando el Gobierno la usa y publica la norma (art. 82.3 CE). Solo sirve una vez.","No. Sí pueden. Sin perjuicio de la competencia de los Tribunales, las leyes de delegación “podrán establecer” fórmulas adicionales de control (art. 82.6 CE)."]},{"id":"vo-01-016","origen":"votaciones","test":"Clase 1 - Bloque III","n":16,"enunciado":"Conforme a lo previsto en la Constitución Española, ¿qué órgano convalida los decretos-leyes? (GACE-LI 2014)","opciones":["El Gobierno.","Las Cortes Generales.","El Congreso.","El Senado."],"bloque":"fuentes","precepto":"Art. 86.2 de la Constitución","correcta":2,"justificaciones":["No. El Gobierno es quien dicta el decreto-ley (art. 86.1 CE). No puede ser también quien lo convalide, que es dar el visto bueno a lo que ha hecho.","No. Es demasiado amplio. Las Cortes Generales son Congreso y Senado, y aquí solo interviene el Congreso (art. 86.2 CE).","Es esta. El **art. 86.2 CE** dice que el Congreso de los Diputados se pronuncia expresamente sobre su convalidación o derogación, en los treinta días siguientes a su promulgación.","No. El Senado no participa en la convalidación. El art. 86.2 CE solo habla del Congreso."],"ojo":"La trampa típica es “Cortes Generales”. Las Cortes sí aparecen en el art. 86.3 CE, para tramitarlo después como proyecto de ley, pero eso es otra cosa."},{"id":"vo-01-017","origen":"votaciones","test":"Clase 1 - Bloque III","n":17,"enunciado":"De conformidad con lo establecido en el artículo 86 de la Constitución Española, el Real Decreto-Ley: (ADMVO-LI 2019)","opciones":["Se aprueba por el Gobierno, previa delegación del Congreso de las Diputados, en un plazo máximo de 30 días.","Tiene el mismo rango jerárquico normativo que el Real Decreto del Consejo de Ministros.","Debe ser inmediatamente sometido a debate y votación de totalidad al Congreso de las Diputados.","Se convalida por el Congreso de las Diputados y por el Senado."],"bloque":"fuentes","precepto":"Art. 86.2 de la Constitución","correcta":2,"justificaciones":["No. No hay delegación previa: el Gobierno lo dicta por sí mismo si hay extraordinaria y urgente necesidad (art. 86.1 CE). Los 30 días son para el pronunciamiento del Congreso, después de promulgado.","No. El decreto-ley tiene rango de ley, es una disposición legislativa provisional (art. 86.1 CE). El Real Decreto del Consejo de Ministros es un reglamento, y está por debajo.","Es esta. Es casi literal el **art. 86.2 CE**: debe someterse “inmediatamente” a debate y votación de totalidad en el Congreso, convocado al efecto si no estuviera reunido, en los treinta días siguientes a su promulgación.","No. Sobra el Senado. Solo lo convalida el Congreso (art. 86.2 CE)."]},{"id":"vo-01-018","origen":"votaciones","test":"Clase 1 - Bloque III","n":18,"enunciado":"¿En qué se diferencia un decreto-ley de un decreto legislativo? (ADMVO-PI 2021)","opciones":["En que el decreto legislativo no puede versar sobre materias reservadas a una ley orgánica y el decreto-ley sí.","En que el decreto legislativo está previsto para redacción de textos articulados y el decreto-ley para refundir varios textos legales en uno solo.","En que el decreto-ley necesita de una ley de bases que determine el alcance de su regulación y el decreto legislativo una ley ordinaria.","En que el decreto-ley es una disposición legislativa provisional que se dicta por el Gobierno en caso de extraordinaria y urgente necesidad; y el decreto legislativo es fruto de una delegación expresa de las Cortes Generales en el Gobierno para dictar normas con rango de ley sobre materias determinadas."],"bloque":"fuentes","precepto":"Arts. 82 y 86 de la Constitución","correcta":3,"justificaciones":["No. Que el decreto legislativo no puede entrar en materias de ley orgánica es cierto (art. 82.1 CE). Lo falso es que el decreto-ley “sí” pueda: la Constitución no le da ese permiso y su art. 86.1 le pone sus propios límites (por ejemplo, los derechos del Título I y el Derecho electoral general).","No. Eso no distingue a uno de otro: redactar textos articulados y refundir textos son las dos variantes del decreto legislativo (art. 82.2 CE). El decreto-ley no sirve para ninguna de ellas, sino para la urgencia.","No. El decreto-ley no necesita ninguna ley previa, lo dicta el Gobierno directamente (art. 86.1 CE). Quien necesita ley de delegación es el decreto legislativo: ley de bases o ley ordinaria, según el caso (art. 82.2 CE).","Es esta. Resume bien los dos: el decreto-ley es provisional y nace de la extraordinaria y urgente necesidad (**art. 86.1 CE**); el decreto legislativo nace de una delegación expresa de las Cortes sobre materia determinada (**art. 82.1 y 82.3 CE**). Para recordarlo: uno es por urgencia, el otro por encargo."]},{"id":"vo-07-001","origen":"votaciones","test":"Clase de repaso 1- Bloque III","n":1,"enunciado":"Según el artículo 1 del Código Civil, señale la incorrecta:","opciones":["Carecerán de validez las disposiciones que contradigan otra de rango superior.","La costumbre solo regirá en defecto de ley, siempre que no sea contraria a la moral o al orden público y que resulte probada.","Los usos jurídicos que sean meramente interpretativos de una declaración de voluntad tendrán la consideración de costumbre.","Los principios generales del derecho se aplicarán en defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico."],"bloque":"fuentes","precepto":"Art. 1.3 del Código Civil","correcta":2,"justificaciones":["Es verdadera, así que no se marca. Es el art. 1.2 CC: una norma no puede contradecir a otra de rango superior.","Es verdadera, así que no se marca. Es el art. 1.3 CC: la costumbre va detrás de la ley, no puede ir contra la moral ni el orden público, y hay que probarla.","Esta es la falsa, y por eso es la que hay que marcar. El **art. 1.3 CC** dice justo lo contrario: tienen consideración de costumbre los usos jurídicos que “no sean” meramente interpretativos. Los que solo sirven para interpretar lo que alguien quiso decir no son costumbre.","Es verdadera, así que no se marca. Es el art. 1.4 CC: los principios se aplican si no hay ley ni costumbre, y además informan todo el ordenamiento."],"ojo":"Solo sobra una palabra: han quitado el “no” de “que no sean meramente interpretativos”. Lee despacio estas frases casi calcadas."},{"id":"vo-07-002","origen":"votaciones","test":"Clase de repaso 1- Bloque III","n":2,"enunciado":"Según el Código Civil, la jurisprudencia: (Castilla la Mancha A2 – 2025)","opciones":["Siempre que proceda de la doctrina establecida por el Tribunal Supremo tendrá la consideración de fuente del ordenamiento jurídico español.","Complementará el ordenamiento jurídico con la doctrina que, de modo reiterado, establezca el Tribunal Supremo al interpretar y aplicar la Ley, la costumbre y los principios generales del derecho.","Complementará el ordenamiento jurídico con la doctrina que establezca cualquier órgano jurisdiccional colegiado.","Complementará el ordenamiento jurídico con la doctrina que, de modo reiterado, establezca el Tribunal Supremo al modificar la Ley, la costumbre y los principios generales del derecho."],"bloque":"fuentes","precepto":"Art. 1.6 del Código Civil","correcta":1,"justificaciones":["No. La jurisprudencia no es fuente del ordenamiento: las fuentes son ley, costumbre y principios generales (art. 1.1 CC). La jurisprudencia solo las “complementa”.","Es esta. Lo dice casi literal el **art. 1.6 CC**: complementa el ordenamiento con la doctrina que, de modo reiterado, establece el Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales. Recuerda tres claves: reiterada, Tribunal Supremo, interpretar y aplicar.","No. Te han cambiado el Tribunal Supremo por “cualquier órgano jurisdiccional colegiado”. Solo cuenta la doctrina del Tribunal Supremo.","No. Te han cambiado “interpretar y aplicar” por “modificar”. Los jueces no cambian la ley: la interpretan y la aplican."]},{"id":"vo-07-003","origen":"votaciones","test":"Clase de repaso 1- Bloque III","n":3,"enunciado":"De conformidad con el artículo 2 del Código Civil, las leyes entrarán en vigor:","opciones":["El día de su publicación en el BOE.","Al día siguiente de su publicación en el BOE, salvo que dispongan otra cosa.","A los 20 días de su firma, salvo que dispongan otra cosa.","A los 20 días de su publicación en el BOE, salvo que dispongan otra cosa."],"bloque":"fuentes","precepto":"Art. 2.1 del Código Civil","correcta":3,"justificaciones":["No. La regla general no es el mismo día de la publicación, sino a los veinte días (art. 2.1 CC). Una ley puede fijar el mismo día, pero tiene que decirlo ella.","No. El día siguiente a la publicación es una fórmula muy habitual en las leyes, pero no es la regla del Código Civil. La regla son veinte días si la ley no dice otra cosa.","No. Los veinte días se cuentan desde la completa publicación en el BOE, no desde la firma.","Es esta. El **art. 2.1 CC** dice que las leyes entran en vigor a los veinte días de su completa publicación en el BOE, si en ellas no se dispone otra cosa. Ese tiempo de espera entre publicación y entrada en vigor se llama “vacatio legis”."]},{"id":"vo-07-004","origen":"votaciones","test":"Clase de repaso 1- Bloque III","n":4,"enunciado":"En relación con la jerarquía de las normas reglamentarias:","opciones":["Real Decreto-Ley es superior a una Orden Ministerial.","Real Decreto del Consejo de Ministros es superior a una Orden Ministerial.","Real Decreto del Presidente del Gobierno es superior al Real Decreto del Consejo de Ministros.","Todos los reglamentos tienen el mismo nivel de jerarquía."],"bloque":"fuentes","precepto":"Art. 24.2 de la Ley 50/1997","correcta":1,"justificaciones":["No. El Real Decreto-ley no es un reglamento: es una norma con rango de ley (art. 86 CE y art. 24.1.a de la Ley 50/1997). La pregunta va de jerarquía entre normas reglamentarias, así que no encaja aquí.","Es esta. El **art. 24.2 de la Ley 50/1997** ordena los reglamentos en dos escalones: arriba, los aprobados por Real Decreto del Presidente o acordado en Consejo de Ministros; debajo, los aprobados por Orden Ministerial.","No. Los dos Reales Decretos están en el mismo escalón: el art. 24.2 los pone juntos en el primer nivel, sin que uno esté por encima del otro.","No. Sí hay jerarquía entre reglamentos: el art. 24.2 fija dos niveles. El Real Decreto va por encima de la Orden Ministerial."],"ojo":"La primera opción es cierta si la lees suelta, porque un decreto-ley está por encima de una orden. Pero falla por el tema: no es una norma reglamentaria."},{"id":"vo-07-005","origen":"votaciones","test":"Clase de repaso 1- Bloque III","n":5,"enunciado":"Las leyes o reglamentos que impongan nuevas obligaciones a las personas que desempeñen una actividad económica o profesional, ¿cuándo preverán el comienzo de su vigencia?","opciones":["A los 20 días de su completa publicación en el BOE, si en ellas no se dispone otra cosa.","Si se aprobó el Reglamento el 03/01/2025, entrará en vigor el 02/01/2026.","Si se aprobó el Reglamento el 03/01/2025, entrará en vigor el 01/07/2025.","El 1 de enero o el 2 de julio siguientes a su aprobación."],"bloque":"fuentes","precepto":"Art. 23 de la Ley 50/1997","correcta":2,"justificaciones":["No. Esa es la regla general del art. 2.1 CC. Para normas que imponen nuevas obligaciones a quien ejerce una actividad económica o profesional, hay una regla especial con fechas fijas (art. 23 de la Ley 50/1997).","No. El 2 de enero es una de las dos fechas, pero el art. 23 pide la siguiente a la aprobación. Tras el 3 de enero de 2025, la primera que llega es el 1 de julio de 2025, no el 2 de enero de 2026.","Es esta. El **art. 23 de la Ley 50/1997** fija el comienzo de la vigencia el 2 de enero o el 1 de julio siguientes a la aprobación. Como el reglamento se aprueba el 3 de enero de 2025, ya ha pasado el 2 de enero de ese año, y la siguiente fecha es el 1 de julio de 2025.","No. Te han cruzado las fechas. Son el 2 de enero y el 1 de julio, no el 1 de enero y el 2 de julio."],"ojo":"Truco para recordarlo: 2 de enero y 1 de julio. Esta regla no se aplica a los reales decretos-leyes, ni cuando lo aconseje la transposición de directivas u otras razones justificadas."},{"id":"vo-07-007","origen":"votaciones","test":"Clase de repaso 1- Bloque III","n":7,"enunciado":"¿Cuándo podrá una ley de bases autorizar a la modificación de la propia ley de bases? (GVA A1 – 2025)","opciones":["Siempre que la modificación no tenga carácter retroactivo.","En aquellos casos en que el objeto de la ley de bases no sea la refundición de varios textos legales en uno solo.","Cuando el objeto de la ley de bases sea la refundición de textos legales que previsiblemente pudieran resultar afectados por la tramitación de iniciativas legislativas en curso.","En ningún caso."],"bloque":"fuentes","precepto":"Art. 83.a) de la Constitución","correcta":3,"justificaciones":["No. Aunque la modificación no fuera retroactiva, seguiría prohibida. Lo de la retroactividad es otra prohibición distinta (art. 83.b CE).","No. Refundir varios textos legales en uno se hace por ley ordinaria, no por ley de bases (art. 82.2 CE). Y que la ley de bases tenga otro objeto no le permite autorizar su propia modificación.","No. Esa excepción no existe. Además, la refundición no se delega con ley de bases, sino con ley ordinaria (art. 82.2 CE).","Es esta. El **art. 83.a) CE** dice que las leyes de bases no podrán “en ningún caso” autorizar la modificación de la propia ley de bases. No hay excepciones."],"ojo":"El art. 83 CE tiene dos prohibiciones: autorizar la modificación de la propia ley de bases y facultar para dictar normas con carácter retroactivo."},{"id":"vo-07-008","origen":"votaciones","test":"Clase de repaso 1- Bloque III","n":8,"enunciado":"De conformidad con el artículo 86 de la Constitución Española de 1978, los Decretos-leyes deberán ser inmediatamente sometidos a debate y votación de totalidad al Congreso de los Diputados: (La Rioja A2 – 2022)","opciones":["En el plazo de los quince días siguientes a su promulgación.","En el plazo de los treinta días siguientes a su promulgación.","En el plazo de los veinte días siguientes a su promulgación.","En el plazo de los diez días siguientes a su promulgación."],"bloque":"fuentes","precepto":"Art. 86.2 de la Constitución","correcta":1,"justificaciones":["No. Te han cambiado el plazo. No son quince días, sino treinta.","Es esta. El **art. 86.2 CE** da treinta días desde la promulgación para someter el decreto-ley a debate y votación de totalidad en el Congreso. Dentro de ese plazo, el Congreso tiene que decidir si lo convalida o lo deroga.","No. Te han cambiado el plazo. Son treinta días; los veinte días te pueden sonar de la entrada en vigor de las leyes (art. 2.1 CC).","No. Te han cambiado el plazo. No son diez días, sino treinta."]},{"id":"vo-07-009","origen":"votaciones","test":"Clase de repaso 1- Bloque III","n":9,"enunciado":"Señale la respuesta correcta en relación con el Decreto Legislativos y el Decreto Ley:","opciones":["El Decreto Ley deberá ser inmediatamente sometido a debate y votación de totalidad al Congreso de los Diputados, convocado al efecto si no estuviere reunido, en el plazo de 20 días siguientes a su promulgación.","El Decreto Legislativo es dictado por el gobierno, debido a la situación de extraordinaria y urgente necesidad.","El Decreto Ley es una disposición reglamentaria.","El Decreto Legislativo se agota por el uso que haga el gobierno mediante la publicación de la norma."],"bloque":"fuentes","precepto":"Art. 82.3 de la Constitución","correcta":3,"justificaciones":["No. Todo es correcto menos el plazo: el art. 86.2 CE da treinta días, no veinte.","No. Te han cruzado las dos figuras. La extraordinaria y urgente necesidad es propia del Decreto-ley (art. 86.1 CE). El Decreto Legislativo nace de una delegación de las Cortes (art. 82.1 CE).","No. El Decreto-ley no es un reglamento: tiene rango de ley. El art. 86.1 CE lo llama “disposiciones legislativas provisionales”.","Es esta. El **art. 82.3 CE** dice que la delegación se agota por el uso que de ella haga el Gobierno mediante la publicación de la norma. Dicho de otro modo: el Gobierno recibe el permiso de las Cortes, lo usa una vez publicando la norma y ya no puede volver a usarlo."],"ojo":"Para no confundirlos: Decreto Legislativo, delegación de las Cortes. Decreto-ley, urgencia, y luego convalidación en el Congreso."},{"id":"pr-06-001","origen":"practicas","test":"Examen nº 1","n":1,"enunciado":"En relación con las Fuentes del Derecho, el artículo 1 del Código Civil establece que:","opciones":["Los usos jurídicos que sean meramente interpretativos de una declaración de voluntad tendrán la consideración de costumbre.","Son fuentes del derecho la ley, la costumbre y la jurisprudencia reiterada del Tribunal Supremo.","Los principios generales del derecho se aplicarán en defecto de ley o costumbre.","Las normas jurídicas contenidas en los tratados internacionales serán de aplicación directa en España."],"bloque":"fuentes","precepto":"Art. 1.4 del Código Civil","correcta":2,"justificaciones":["No. Te han quitado el “no”. Según el art. 1.3 CC tienen consideración de costumbre los usos jurídicos que **no** sean meramente interpretativos de una declaración de voluntad.","No. Las tres fuentes del art. 1.1 CC son la ley, la costumbre y los **principios generales del derecho**. La jurisprudencia no es fuente: solo “complementa” el ordenamiento (art. 1.6 CC).","Es esta. Es casi literal el **art. 1.4 CC**: los principios generales se aplican cuando no hay ley ni costumbre. Son el último recurso, aunque además inspiran todo el ordenamiento.","No. El art. 1.5 CC dice justo lo contrario: los tratados **no** se aplican directamente en España hasta que forman parte del ordenamiento interno con su publicación íntegra en el BOE."],"ojo":"Orden que debes recordar: ley, costumbre y principios generales. La jurisprudencia queda fuera de la lista y es la trampa típica."},{"id":"pr-06-002","origen":"practicas","test":"Examen nº 1","n":2,"enunciado":"De acuerdo con lo dispuesto en el artículo 2 del Código Civil, ¿cuándo entran en vigor las leyes?","opciones":["En todo caso, a los veinte días de su completa publicación en el BOE.","Desde el mismo día de su completa publicación en el BOE.","Desde el día siguiente de su completa publicación en el BOE","En la fecha que en ellas se disponga y, en su defecto, a los veinte días de su completa publicación en el BOE."],"bloque":"fuentes","precepto":"Art. 2.1 del Código Civil","correcta":3,"justificaciones":["No. Sobra “en todo caso”. Los veinte días solo se aplican si la propia ley no dice otra cosa (art. 2.1 CC).","No. La regla general no es el mismo día de la publicación. Una ley puede entrar en vigor ese día solo si ella misma lo dispone; si calla, son veinte días.","No. El día siguiente tampoco es la regla general. Una ley puede fijarlo, pero si no dice nada se aplican los veinte días.","Es esta. El **art. 2.1 CC** dice que las leyes entran en vigor a los veinte días de su completa publicación en el BOE “si en ellas no se dispone otra cosa”. Primero manda lo que diga la ley; si no dice nada, veinte días. Ese tiempo de espera se llama “vacatio legis”."]},{"id":"pr-06-003","origen":"practicas","test":"Examen nº 1","n":3,"enunciado":"Señale la respuesta correcta en relación al principio de jerarquía normativa:","opciones":["La leyes emanadas de las Cortes Generales son jerárquicamente superiores a las leyes de una Comunidad Autónoma.","Las leyes orgánicas son jerárquicamente superiores a las leyes ordinarias.","Un Real Decreto del Presidente del Gobierno tiene el mismo rango jerárquico que un Real Decreto del Consejo de Ministros.","Las leyes están jerarquizadas entre sí, hallándose su rango en función del nivel del órgano del que emanan."],"bloque":"fuentes","precepto":"Art. 24.2 de la Ley 50/1997","correcta":2,"justificaciones":["No. Las leyes estatales y las autonómicas tienen el mismo rango, el de ley. No se diferencian por jerarquía, sino por las materias que le corresponden a cada una.","No. Es la confusión más típica. La ley orgánica no tiene más rango que la ordinaria: cada una regula sus materias (art. 81 CE). Se diferencian por la materia, no por la jerarquía.","Es esta. El **art. 24.2 de la Ley 50/1997** coloca en el primer escalón de los reglamentos, juntas, las disposiciones aprobadas por Real Decreto del Presidente del Gobierno o acordado en Consejo de Ministros. En el segundo escalón están las Órdenes Ministeriales.","No. Las leyes no están jerarquizadas entre sí, todas tienen el mismo rango de ley. Lo de ordenar por el nivel del órgano del que emanan se parece más a lo que ocurre con los reglamentos (art. 24.2 de la Ley 50/1997)."],"ojo":"Entre normas con rango de ley no hay jerarquía, solo reparto de materias. La jerarquía de escalones aparece en los reglamentos."},{"id":"pr-06-004","origen":"practicas","test":"Examen nº 1","n":4,"enunciado":"Según el artículo 24 de la Ley 50/1997, del Gobierno, las decisiones del Gobierno de la Nación y de sus miembros revisten la forma siguiente:","opciones":["Orden del Ministro de la Presidencia, las disposiciones y resoluciones de los Ministros que afecten a varios Departamentos.","Acuerdos del Consejo de Ministros, las decisiones que aprueben normas reglamentarias.","Órdenes Ministeriales, las disposiciones y resoluciones de los Ministros y Secretarios de Estado.","Reales Decretos, las disposiciones y resoluciones adoptadas en Comisiones Delegadas del Gobierno."],"bloque":"fuentes","precepto":"Art. 24.1.f) de la Ley 50/1997","correcta":0,"justificaciones":["Es esta. El **art. 24.1.f)** dice que, cuando una disposición o resolución afecta a varios Departamentos (varios Ministerios), toma la forma de **Orden del Ministro de la Presidencia**, dictada a propuesta de los Ministros interesados.","No. Aprobar normas reglamentarias del Consejo de Ministros se hace con **Real Decreto** acordado en Consejo de Ministros (art. 24.1.c). Los Acuerdos son para las decisiones que no deban adoptar esa forma (art. 24.1.d).","No. Sobran los Secretarios de Estado. Las Órdenes Ministeriales son disposiciones y resoluciones de los **Ministros** (art. 24.1.f).","No. Lo que deciden las Comisiones Delegadas del Gobierno son **Acuerdos**, que se plasman en Orden del Ministro competente o del Ministro de la Presidencia (art. 24.1.e). No son Reales Decretos."]},{"id":"pr-06-005","origen":"practicas","test":"Examen nº 1","n":5,"enunciado":"Señale la respuesta correcta en relación con los Decretos Leyes y los Decretos Legislativos:","opciones":["Se encuentran jerárquicamente subordinados a las leyes.","Son disposiciones legislativas dictadas por el Gobierno.","Deberán ser sometidos a debate y votación de totalidad al Congreso de los Diputados, en el mes siguiente a su promulgación.","Son dictados por el Gobierno previa autorización del Congreso de los Diputados."],"bloque":"fuentes","precepto":"Arts. 85 y 86 de la Constitución","correcta":1,"justificaciones":["No. Decretos-leyes y Decretos Legislativos tienen **rango de ley**, el mismo escalón que las leyes de las Cortes. No están por debajo de ellas.","Es esta. Ambos los dicta el Gobierno y tienen fuerza de ley. El **art. 86 CE** llama a los Decretos-leyes “disposiciones legislativas provisionales” y el **art. 85 CE** dice que los Decretos Legislativos contienen legislación delegada. Es el único rasgo que comparten de los que aparecen aquí.","No. Fallan dos cosas: esto solo se aplica a los **Decretos-leyes**, no a los Legislativos, y el plazo es de **treinta días** siguientes a la promulgación, no un mes (art. 86.2 CE).","No. El Decreto-ley no necesita autorización previa: el Gobierno lo dicta por extraordinaria y urgente necesidad. El Decreto Legislativo sí necesita delegación, pero de las **Cortes Generales** y no solo del Congreso (art. 82.1 CE)."],"ojo":"La pregunta habla de los dos a la vez. Una opción que solo vale para uno de ellos no es correcta."},{"id":"pr-13-001","origen":"practicas","test":"Examen nº 2","n":1,"enunciado":"En el marco del sistema de fuentes del Derecho Administrativo español cabe afirmar que:","opciones":["Las leyes entrarán en vigor a partir del día siguiente a su completa publicación en el BOE, si en ellas no se dispone otra cosa.","Las leyes tendrán efecto retroactivo, si no dispusieren lo contrario.","La costumbre solo rige en defecto de ley aplicable, siempre que no sea contraria a la moral u orden público, y resulte probada.","Las normas jurídicas contenidas en tratados internacionales serán de aplicación directa en España desde su ratificación."],"bloque":"fuentes","precepto":"Art. 1.3 del Código Civil","correcta":2,"justificaciones":["No. Te han cambiado el plazo: las leyes entran en vigor a los **veinte días** de su completa publicación en el BOE, si ellas no dicen otra cosa (art. 2.1 CC). No al día siguiente.","No. Es justo al revés: las leyes **no** tienen efecto retroactivo si no dicen lo contrario (art. 2.3 CC). La regla general es que no miran hacia atrás.","Es esta. Es el **art. 1.3 del Código Civil**: la costumbre va detrás de la ley y solo se aplica si no hay ley, si no va contra la moral o el orden público y si se prueba. Recuerda los tres requisitos juntos.","No. Lo que cuenta no es la ratificación, sino la **publicación íntegra en el BOE**: hasta entonces el tratado no forma parte del Derecho interno ni se aplica directamente (art. 1.5 CC y art. 96.1 CE)."],"ojo":"La regla de la “vacatio legis” (el tiempo entre publicar y entrar en vigor) son 20 días. El “día siguiente” es lo que muchas leyes disponen por su cuenta, pero no es la regla general."},{"id":"pr-13-002","origen":"practicas","test":"Examen nº 2","n":2,"enunciado":"Señale la respuesta correcta en relación con los Decretos Leyes a que se refiere el artículo 86 de la Constitución Española:","opciones":["Tienen el mismo rango jerárquico normativo que una ley orgánica.","En caso de extraordinaria y urgente necesidad, las Cortes Generales podrán dictar Decretos-leyes.","Deben ser inmediatamente sometido a debate y votación de totalidad a las Cortes Generales.","En caso de extraordinaria y urgente necesidad podrán afectar a las instituciones básicas del Estado."],"bloque":"fuentes","precepto":"Art. 86 de la Constitución","correcta":0,"justificaciones":["Es esta. El decreto-ley es una disposición con **rango de ley** (**art. 86.1 CE**), y todas las normas con rango de ley están en el mismo escalón: ley orgánica, ley ordinaria, decreto-ley. La ley orgánica no es superior: se distingue por la materia que regula, no por su rango.","No. Te han cambiado quién lo dicta: los decretos-leyes los dicta **el Gobierno**, no las Cortes Generales (art. 86.1 CE).","No. Se someten a debate y votación de totalidad **en el Congreso de los Diputados**, no en las Cortes Generales, en los 30 días siguientes a su promulgación (art. 86.2 CE). El Senado no interviene en la convalidación.","No. Es al revés: los decretos-leyes **no pueden** afectar al ordenamiento de las instituciones básicas del Estado, por muy urgente que sea el caso (art. 86.1 CE)."],"ojo":"Parece raro que sea correcta la opción A, pero es una pregunta clásica: ley orgánica y decreto-ley tienen el mismo rango. Lo que no puede hacer el decreto-ley es entrar en las materias vedadas por el art. 86.1 CE."},{"id":"pr-13-003","origen":"practicas","test":"Examen nº 2","n":3,"enunciado":"En relación con las fuentes del derecho administrativo, y de conformidad con lo establecido en el artículo 1 del Código Civil, señale cuál de las siguientes opciones es correcta:","opciones":["Los Jueces y Tribunales podrán abstenerse de resolver so pretexto de insuficiencia legislativa.","Son fuentes del ordenamiento jurídico la ley, la costumbre, los principios generales del derecho y la jurisprudencia.","La jurisprudencia que de modo reiterado establezca el Tribunal Supremo solo regirá en defecto de ley aplicable.","Los usos jurídicos que no sean meramente interpretativos de una declaración de voluntad tendrán la consideración de costumbre."],"bloque":"fuentes","precepto":"Art. 1.3 del Código Civil","correcta":3,"justificaciones":["No. Es lo contrario: los jueces tienen el **deber inexcusable de resolver** en todo caso los asuntos de que conozcan (art. 1.7 CC). No pueden escudarse en que la ley no alcanza.","No. Sobra la jurisprudencia. Las fuentes son solo tres: ley, costumbre y principios generales del derecho (art. 1.1 CC). La jurisprudencia no es fuente: **complementa** el ordenamiento (art. 1.6 CC).","No. Te han puesto a la jurisprudencia la frase de la costumbre. “En defecto de ley aplicable” es del art. 1.3. La jurisprudencia del Tribunal Supremo no “rige”: complementa el ordenamiento (art. 1.6 CC).","Es esta. Es casi literal el párrafo segundo del **art. 1.3 CC**. Un uso jurídico que hace algo más que aclarar lo que quisieron decir las partes vale como costumbre."],"ojo":"Ojo con la opción B: es la trampa más repetida de este artículo. Ley, costumbre y principios: tres fuentes, sin jurisprudencia."},{"id":"pr-13-004","origen":"practicas","test":"Examen nº 2","n":4,"enunciado":"Según el artículo 24 de la Ley 50/1997, los reglamentos se ordenarán según la siguiente jerarquía:","opciones":["1º. Disposiciones aprobadas por Real Decreto del Presidente del Gobierno. 2º. Disposiciones acordadas por Real Decreto en Consejo de Ministros. 3º Disposiciones aprobadas por Orden Ministerial.","1º. Disposiciones aprobadas por Real Decreto del Presidente del Gobierno o por Real Decreto acordado en Consejo de Ministros. 2º Disposiciones aprobadas por Orden Ministerial.","1º Disposiciones acordadas en Consejo de Ministros. 2º Disposiciones aprobadas por Real Decreto del Presidente del Gobierno.","Todas las normas reglamentarias tienen el mismo rango jerárquico."],"bloque":"fuentes","precepto":"Art. 24.2 de la Ley 50/1997","correcta":1,"justificaciones":["No. Separa en dos escalones lo que la ley pone en uno solo. El Real Decreto del Presidente y el acordado en Consejo de Ministros están **al mismo nivel** (art. 24.2).","Es esta. El **art. 24.2 de la Ley 50/1997** solo tiene dos escalones: primero, el Real Decreto (del Presidente o acordado en Consejo de Ministros); segundo, la Orden Ministerial.","No. Se inventa un orden entre ambos y deja fuera la Orden Ministerial. Consejo de Ministros y Presidente comparten escalón, y por debajo está la Orden (art. 24.2).","No. Sí hay jerarquía entre reglamentos: la Orden Ministerial está por debajo del Real Decreto (art. 24.2)."],"ojo":"Recuerda: dos escalones, no tres. Y el Real Decreto va primero sea del Presidente o del Consejo de Ministros."},{"id":"pr-13-005","origen":"practicas","test":"Examen nº 2","n":5,"enunciado":"Según el artículo 83 de la Constitución Española, las leyes de bases:","opciones":["Podrán facultar para dictar normas con carácter retroactivo.","Podrán habilitar al Gobierno para dictar disposiciones legislativas provisionales.","No podrán en ningún caso autorizar la modificación de la propia ley de bases.","No podrán delimitar el objeto y alcance de la delegación legislativa."],"bloque":"fuentes","precepto":"Art. 83 de la Constitución","correcta":2,"justificaciones":["No. Es una de las dos cosas prohibidas: las leyes de bases **no pueden** facultar para dictar normas con carácter retroactivo (art. 83.b CE).","No. Esa frase es de otra figura: las “disposiciones legislativas provisionales” son los **decretos-leyes** (art. 86.1 CE). Las leyes de bases sirven para que el Gobierno elabore textos articulados (art. 82.2 CE).","Es esta. El **art. 83.a) CE** prohíbe que una ley de bases autorice su propia modificación. Tiene sentido: el Gobierno recibe el encargo de desarrollar las bases, no de cambiarlas.","No. Es lo contrario: las leyes de bases **deben** delimitar con precisión el objeto y alcance de la delegación (art. 82.4 CE)."],"ojo":"El art. 83 CE es corto: solo dos prohibiciones, modificar la propia ley de bases y permitir normas retroactivas."},{"id":"pr-39-009","origen":"practicas","test":"Ley 39 + Ley 40 - Examen (30 preguntas)","n":9,"enunciado":"Conforme a lo establecido en el artículo 1 del Código Civil, son fuentes del ordenamiento jurídico español:","opciones":["La ley, la costumbre y la jurisprudencia.","La ley, la costumbre, los principios generales del derecho y la jurisprudencia.","La Constitución y la ley.","La ley, la costumbre y los principios generales del derecho."],"bloque":"fuentes","precepto":"Art. 1.1 del Código Civil","correcta":3,"justificaciones":["No. La jurisprudencia no es fuente del ordenamiento: solo lo **complementa** (art. 1.6 CC). Y falta la mención a los principios generales.","No. Se cuela la jurisprudencia, que el **art. 1.1** no cita como fuente. Complementa el ordenamiento, pero no lo forma.","No. La Constitución es norma suprema, pero el **art. 1.1 CC** enumera tres fuentes: ley, costumbre y principios generales del derecho. Le faltan dos.","Es esta. El **art. 1.1 del Código Civil** dice: las fuentes del ordenamiento jurídico español son la ley, la costumbre y los principios generales del derecho."]},{"id":"pr-39-015","origen":"practicas","test":"Ley 39 + Ley 40 - Examen (30 preguntas)","n":15,"enunciado":"Según el artículo 24 de la Ley 50/1997, los reglamentos se ordenarán según la siguiente jerarquía:","opciones":["1º Las disposiciones que son aprobadas por Real Decreto del Presidente del Gobierno o acordadas en el Consejo de Ministros; 2º Las disposiciones aprobadas por Orden Ministerial.","1º Las disposiciones aprobadas por Real Decreto del Presidente del Gobierno; 2º Las disposiciones acordadas por el Consejo de Ministros; 3º Las disposiciones aprobadas por Orden Ministerial.","1º Las disposiciones aprobadas por el Consejo de Ministros; 2º Las disposiciones aprobadas por Real Decreto del Presidente del Gobierno; 3º Las disposiciones aprobadas por Orden Ministerial.","Todas las normas reglamentarias tienen el mismo rango jerárquico."],"bloque":"fuentes","precepto":"Art. 24.2 de la Ley 50/1997","correcta":0,"justificaciones":["Es esta. El **art. 24.2** de la Ley del Gobierno ordena los reglamentos en dos niveles: primero, los aprobados por Real Decreto del Presidente del Gobierno o acordados en Consejo de Ministros; segundo, los aprobados por Orden Ministerial.","No. Separa en dos niveles distintos el Real Decreto del Presidente y los acordados en Consejo de Ministros. El **art. 24.2** los pone en el mismo primer nivel.","No. Igual que la anterior, parte en dos lo que la ley junta en un único primer nivel (**art. 24.2**), y además inventa un orden entre ellos.","No. Sí hay jerarquía. Las disposiciones de Real Decreto están por encima de las Órdenes Ministeriales (**art. 24.2**)."],"ojo":"Solo hay dos peldaños: Real Decreto (del Presidente o del Consejo de Ministros) y, debajo, Orden Ministerial."},{"id":"pr-39-026","origen":"practicas","test":"Ley 39 + Ley 40 - Examen (30 preguntas)","n":26,"enunciado":"Conforme al artículo 2 del Código Civil, si en las leyes no se dispone otra cosa, ¿cuándo entrarán estas en vigor?","opciones":["A los quince días de su completa publicación en el Boletín Oficial del Estado.","A los veinte días de su completa publicación en el Boletín Oficial del Estado.","A los treinta días de su completa publicación en el Boletín Oficial del Estado.","Al día siguiente de su completa publicación en el Boletín Oficial del Estado."],"bloque":"fuentes","precepto":"Art. 2.1 del Código Civil","correcta":1,"justificaciones":["No. Quince días no es el plazo del **art. 2.1 CC**.","Es esta. El **art. 2.1 del Código Civil** dice que, si la ley no dispone otra cosa, entra en vigor a los **veinte días** de su completa publicación en el BOE.","No. Treinta días no es el plazo del **art. 2.1 CC**.","No. Entrar en vigor al día siguiente solo ocurre si la propia ley lo dice. La regla general es de veinte días (**art. 2.1 CC**)."]},{"id":"pr-39-028","origen":"practicas","test":"Ley 39 + Ley 40 - Examen (30 preguntas)","n":28,"enunciado":"¿Qué forma adoptarán las decisiones del Consejo de Ministros que NO deban adoptar la forma de Real Decreto, según el artículo 24 de la Ley 50/1997, de 27 de noviembre, del Gobierno?","opciones":["Órdenes del Consejo de Ministros.","Resoluciones del Consejo de Ministros.","Reglamentos del Consejo de Ministros.","Acuerdos del Consejo de Ministros."],"bloque":"fuentes","precepto":"Art. 24.1.d) de la Ley 50/1997","correcta":3,"justificaciones":["No. Las “Órdenes” son la forma de las disposiciones de los Ministros (**art. 24.1.f**) y de los acuerdos de las Comisiones Delegadas.","No. “Resoluciones del Consejo de Ministros” no es una forma que recoja el **art. 24.1**.","No. “Reglamentos del Consejo de Ministros” no existe como forma: los reglamentos del Consejo de Ministros adoptan la forma de Real Decreto (**art. 24.1.c**).","Es esta. El **art. 24.1.d** dice que las decisiones del Consejo de Ministros que no deban adoptar la forma de Real Decreto son **Acuerdos** del Consejo de Ministros."]},{"id":"pr-39-029","origen":"practicas","test":"Ley 39 + Ley 40 - Examen (30 preguntas)","n":29,"enunciado":"Siguiendo lo dispuesto en el artículo 1.5 del Código Civil, ¿en qué momento pasará a formar parte del ordenamiento jurídico interno un tratado internacional válidamente celebrado?","opciones":["Una vez adoptado el tratado internacional.","Una vez publicado en el Boletín Oficial del Estado.","Una vez ratificado por el Congreso de los Diputados.","Una vez publicado en el Boletín Oficial de las Cortes Generales."],"bloque":"fuentes","precepto":"Art. 1.5 del Código Civil","correcta":1,"justificaciones":["No. Adoptarlo no basta. Según el **art. 1.5 CC**, las normas jurídicas de los tratados no son de aplicación directa hasta que pasan a formar parte del ordenamiento interno por su publicación.","Es esta. El **art. 1.5 CC** dice que los tratados internacionales válidamente celebrados, una vez publicados oficialmente en España, forman parte del ordenamiento interno. La publicación es en el BOE.","No. La ratificación o autorización por las Cortes puede ser necesaria para celebrarlo, pero lo que lo incorpora al ordenamiento interno es la **publicación** (**art. 1.5 CC**).","No. El Boletín Oficial de las Cortes Generales no es el medio. El tratado se publica en el **Boletín Oficial del Estado** (**art. 1.5 CC**)."]},{"id":"pr-41-043","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":43,"enunciado":"Conforme a la Constitución Española y a la Ley 50/1997, del Gobierno, el Real Decreto-Ley 36/2020, de 30 de diciembre, por el que se aprueban medidas urgentes para la modernización de la Administración Pública y la ejecución del Plan de Recuperación, Transformación y Resiliencia:","opciones":["Precisó para su aprobación de una previa Ley de Bases que otorgara al Gobierno esa delegación legislativa.","Posee el mismo rango jerárquico que los Reales Decretos acordados en el Consejo de Ministros.","Es una disposición reglamentaria provisional dictada por el Gobierno en caso de extraordinaria y urgente necesidad.","Una vez aprobado hubo de ser sometido a debate y votación de totalidad al Congreso de los Diputados."],"bloque":"fuentes","precepto":"Art. 86 de la Constitución y art. 24.1.a) de la Ley 50/1997","correcta":3,"justificaciones":["No. La delegación legislativa con una ley de bases es la vía de los **Decretos Legislativos** (art. 82 CE). Un Real Decreto-ley no necesita ninguna ley previa que lo habilite.","No. Un Real Decreto-ley tiene **rango de ley**, mientras que un Real Decreto acordado en Consejo de Ministros es una norma reglamentaria. No tienen el mismo rango.","No. Es una disposición **legislativa** provisional, no reglamentaria (**art. 86 CE**). Se dicta por el Gobierno en caso de extraordinaria y urgente necesidad.","Es esta. El **art. 86.2 CE** manda someter los decretos-leyes a debate y votación de totalidad en el Congreso de los Diputados en los treinta días siguientes a su promulgación, para su convalidación o derogación."],"ojo":"Decreto-ley: urgente, rango de ley, provisional y con convalidación en treinta días. Decreto legislativo: delegación previa de las Cortes."},{"id":"pr-41-044","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":44,"enunciado":"De acuerdo con lo establecido en el artículo 2 del Código Civil:","opciones":["Las leyes no tendrán efecto retroactivo, si no dispusieren lo contrario.","Las leyes tendrán efecto retroactivo siempre que beneficien al interesado.","Si en ellas no se dispone otra cosa, las leyes entrarán en vigor a los quince días de su completa publicación en el BOE.","La derogación de una ley implica que recobren vigencia las que esta hubiere derogado."],"bloque":"fuentes","precepto":"Art. 2 del Código Civil","correcta":0,"justificaciones":["Es esta. El **art. 2.3 del Código Civil** dice que las leyes no tendrán efecto retroactivo si no dispusieren lo contrario.","No. No hay retroactividad por el solo hecho de que beneficie al interesado. Solo si la propia ley lo dispone (**art. 2.3 CC**), aunque la Constitución prohíbe la de normas restrictivas de derechos individuales.","No. La regla general es de **veinte días**, no de quince (**art. 2.1 CC**).","No. La derogación de la ley derogatoria no hace recobrar vigencia a las leyes que esta había derogado (**art. 2.2 CC**)."]},{"id":"pr-42-004","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (30 preguntas)","n":4,"enunciado":"Conforme al artículo 2 del Código Civil, si en ellas no se dispone otra cosa, las leyes entrarán en vigor: (ADM-LI 2026)","opciones":["A los quince días de su completa publicación en el Boletín Oficial del Estado.","A los veinte días de su completa publicación en el Boletín Oficial del Estado.","A los treinta días de su completa publicación en el Boletín Oficial del Estado.","Al día siguente de su completa publicación en el Boletín Oficial del Estado."],"bloque":"fuentes","precepto":"Art. 2.1 del Código Civil","correcta":1,"justificaciones":["No. Quince días no es el plazo del **art. 2.1 CC**.","Es esta. Si la ley no dispone otra cosa, entra en vigor a los **veinte días** de su completa publicación en el BOE (**art. 2.1 CC**).","No. Treinta días no es el plazo del **art. 2.1 CC**.","No. Al día siguiente solo entra en vigor si la propia ley lo establece. La regla general es de veinte días."]},{"id":"pr-42-019","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (30 preguntas)","n":19,"enunciado":"De acuerdo con el artículo 26 de la Ley 50/1997, de 27 de noviembre, del Gobierno, ¿cuándo podrá prescindirse del trámite de consulta pública en el procedimiento de elaboración de un reglamento? (ADM-LI-EXT 2026)","opciones":["Cuando lo justifiquen causas de necesidad y oportunidad.","Cuando la propuesta normativa tenga un impacto significativo en la actividad económica.","Cuando concurran razones de interés general que lo justifiquen.","Cuando la propuesta regule aspectos parciales de una materia."],"bloque":"fuentes","precepto":"Art. 26.2 de la Ley 50/1997","correcta":3,"justificaciones":["No. La “necesidad y oportunidad” son la materia sobre la que se consulta, no una causa para saltarse la consulta.","No. Es al revés: se puede prescindir cuando la propuesta **no** tenga un impacto significativo en la actividad económica.","No. La ley exige **razones graves de interés público**, no cualquier razón de interés general.","Es esta. El **art. 26.2** permite prescindir de la consulta pública cuando la propuesta regule aspectos parciales de una materia, entre otros supuestos."],"ojo":"Otros supuestos para prescindir: normas presupuestarias u organizativas, razones graves de interés público, sin impacto significativo en la economía o sin obligaciones relevantes para los destinatarios."},{"id":"pr-42-029","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (30 preguntas)","n":29,"enunciado":"Siguiendo lo dispuesto en el artículo 1.5 del Código Civil, ¿en qué momento pasará a formar parte del ordenamiento jurídico interno un tratado internacional válidamente celebrado? (ADM-PI 2026)","opciones":["Una vez adoptado el tratado internacional.","Una vez publicado en el Boletín Oficial del Estado.","Una vez ratificado por el Congreso de los Diputados.","Una vez publicado en el Boletín Oficial de las Cortes Generales."],"bloque":"fuentes","precepto":"Art. 1.5 del Código Civil","correcta":1,"justificaciones":["No. Adoptarlo no basta. El tratado forma parte del ordenamiento interno cuando se publica oficialmente en España (**art. 1.5 CC**).","Es esta. Según el **art. 1.5 CC**, los tratados internacionales válidamente celebrados, una vez publicados oficialmente en España, forman parte del ordenamiento interno. Se publican en el BOE.","No. La autorización de las Cortes puede ser necesaria para celebrarlo, pero lo que lo incorpora es la **publicación** (**art. 1.5 CC**).","No. El Boletín Oficial de las Cortes Generales no es el medio. Es el **Boletín Oficial del Estado**."]},{"id":"pr-42-030","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (30 preguntas)","n":30,"enunciado":"¿Qué forma adoptarán las decisiones del Consejo de Ministros que NO deban adoptar la forma de Real Decreto, según el artículo 24 de la Ley 50/1997, de 27 de noviembre, del Gobierno? (ADM-PI 2026)","opciones":["Órdenes del Consejo de Ministros.","Resoluciones del Consejo de Ministros.","Reglamentos del Consejo de Ministros.","Acuerdos del Consejo de Ministros."],"bloque":"fuentes","precepto":"Art. 24.1.d) de la Ley 50/1997","correcta":3,"justificaciones":["No. Las “Órdenes” son la forma de las disposiciones de los Ministros (**art. 24.1.f**).","No. “Resoluciones del Consejo de Ministros” no es una forma que recoja el **art. 24.1**.","No. “Reglamentos del Consejo de Ministros” no existe como forma: los reglamentos del Consejo de Ministros adoptan la forma de Real Decreto (**art. 24.1.c**).","Es esta. El **art. 24.1.d** dice que las decisiones del Consejo de Ministros que no deban adoptar la forma de Real Decreto son **Acuerdos** del Consejo de Ministros."]}]});
